mapper.sql:
select ee.ENTRUST_STATUS entrustStatus, nvl(efs.ENT_FINISH_AMT, 0) finishAmt, trunc(nvl(efs.ENT_FINISH_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM end, 4) * 100 transactioncom, nvl(tpd.SHARE_AMT, 0) finishDealAmt, trunc(nvl(tpd.SHARE_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM end, 4) * 100 tradeFinishPercent, ee.ENTRUST_NUM entrustNum, ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fpi.ISSUE_DATE issueDate, fpi.PAY_DATE payDate, eed.PORTFOLIO_ID portfolioId, eed.PORTFOLIO_NAME portfolioName, eea.SEC_ACCT_ID secManageAcctId, ssai.SEC_ACCT_NAME secAcctName, eed.INV_AIM businessModel, su.REAL_NAME invManagerName, ee.ENTRUST_DATE entrustDate, to_char(eea.TRANSMIT_TIME, 'hh24:mi:ss') transmitTime, to_char(eea.TRANSMIT_TIME, 'hh24:mi') transmitTimeSer, ee.ENTRUST_ID entrustId, ee.REMARK remark from ETR_ENTRUST ee left join (select listagg(t0.PORTFOLIO_ID, ',') within group (order by t0.ENTRUST_ID) AS PORTFOLIO_ID, listagg(pp.PORTFOLIO_NAME, ',') within group (order by t0.ENTRUST_ID) AS PORTFOLIO_NAME, t0.ENTRUST_ID,t0.INV_AIM from ETR_ENTRUST_DETAIL t0 left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = t0.PORTFOLIO_ID
#{item}
group by t0.ENTRUST_ID,t0.INV_AIM) eed on ee.ENTRUST_ID = eed.ENTRUST_ID left join ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID left join STL_SEC_ACCT_INFO ssai on ssai.SEC_ACCT_ID = eea.SEC_ACCT_ID left join (select sum(ENT_FINISH_AMT) ENT_FINISH_AMT, sum(FINISH_AMT) FINISH_AMT, ENTRUST_ID from ETR_FINISH_STATUS group by ENTRUST_ID) efs on ee.ENTRUST_ID = efs.ENTRUST_ID left join (select sum(t1.SHARE_AMT) SHARE_AMT, t2.ENTRUST_ID from TRD_PRODUCT_DEAL t1 left join TRD_PRODUCT_DEAL_ADD t2 on t1.TRADE_ID = t2.TRADE_ID where t1.IS_CANCEL = #{YN_N} and t1.TRADE_STATUS != #{TRADE_STATUS03} group by t2.ENTRUST_ID) tpd on tpd.ENTRUST_ID = ee.ENTRUST_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = ee.FINPROD_ID left join SYS_USER su on su.USER_NAME = ee.INV_MANAGER_ID where fpi.ISSUE_CLASS = #{ISSUE_CLASS_01} order by decode(ee.ENTRUST_STATUS, '04', 2, '05', 3, '06', 4, 1) asc,fpi.ISSUE_DATE,ee.ENTRUST_DATE,eea.TRANSMIT_TIME

sql.if:
( T.entrustStatus || '|' || sdl_es.item_value || '|' || T.finprodId || '|' || T.finprodMarketId || '|'
    || '|' || T.finprodAbbr || '|' || T.portfolioName || '|' || T.portfolioId || '|' || T.secManageAcctId
    || '|' || T.secAcctName || '|' || T.businessModel || '|' || sdl_bm.item_value
    || '|' || T.invManagerName || '|' || T.entrustId || '|' || T.remark
    like '%' || #{search} || '%'
    or decode(T.transactioncom,0,'0.00',to_char(T.transactioncom,'FM90.90'))=#{search} or to_char(T.transactioncom)=#{search}
    or decode(T.tradeFinishPercent,0,'0.00',to_char(T.tradeFinishPercent,'FM90.90'))=#{search} or to_char(T.tradeFinishPercent)=#{search}
    or decode(T.entrustNum,0,'0.00',to_char(T.entrustNum/10000,'FM999999999990.90'))=#{search} or to_char(T.entrustNum)=#{search}
    or replace(to_char(T.issueDate,'yyyy-MM-dd'),'-','/')=#{search}
    or replace(to_char(T.payDate,'yyyy-MM-dd'),'-','/')=#{search}
    or replace(to_char(T.entrustDate,'yyyy-MM-dd'),'-','/')=#{search}
    or T.transmitTime=#{search}
    )

mapper.select:
select T.entrustStatus, T.finishAmt, T.transactioncom, T.finishDealAmt, T.tradeFinishPercent, T.entrustNum, T.finprodId, T.finprodMarketId, T.finprodAbbr, T.issueDate, T.payDate, T.portfolioId, T.portfolioName, T.secManageAcctId, T.secAcctName, T.businessModel, T.invManagerName, T.entrustDate, T.transmitTime, T.transmitTimeSer, T.entrustId, T.remark from () T left join SYS_DATADICT_LIST sdl_es on T.entrustStatus=sdl_es.ITEM_CODE and sdl_es.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST sdl_bm on T.businessModel=sdl_bm.ITEM_CODE and sdl_bm.DICT_CODE='BUSINESS_MODEL' LEFT JOIN ETR_DISTRIBUTE ed ON ed.ENTRUST_ID = T.entrustId
AND ed.TRADER = #{loginUserId}
AND T.entrustStatus in ('02','03','04','05','06')
AND
#{item}
AND
#{item}
AND
#{item}
AND T.issueDate >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND T.issueDate <= to_date(#{issueDateEnd}, 'yyyy-MM-dd')
AND T.entrustDate >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND T.entrustDate <= to_date(#{entrustDateEnd}, 'yyyy-MM-dd')
AND T.entrustId = #{entrustId} /*指令代码查询*/
AND
#{item}
/*指令代码查询*/
order by ${pageMode.sort} ${pageMode.direction}

     select count(1)  from  (
             select ENTRUST_ID from WFL_BID_ORDER_BID_PRICE

                ENTRUST_ID = #{entrustId}
                /*指令代码查询*/

			union all
			 select ENTRUST_ID from BID_ORDER_BID_PRICE
			 	where IS_CANCEL ='N' and TRADE_STATUS != '03'

                    AND ENTRUST_ID = #{entrustId}
                    /*指令代码查询*/

            )

sql.if:
AND ( T.issueStatus || '|' || sdl_is.item_value || '|' || T.finprodId || '|' || T.finprodMarketId || '|'
|| '|' || T.finprodAbbr || '|' || T.secManageAcctId || '|' || T.secAcctName || '|' || T.issueClass
|| sdl_ist.item_value || '|' || '|' || T.couponSpecies || '|' || sdl_cs.item_value
|| '|' || T.intType || '|' || sdl_it.item_value || '|' || T.ouPartyId || '|' || T.ouPartyIdAbbr
|| '|' || T.issuer || '|' || T.issuerName
like '%' || #{search} || '%'
or decode(T.subscriptionAmount,0,'0.00',to_char(T.subscriptionAmount,'FM999999999990.90'))=#{search} or to_char(T.subscriptionAmount)=#{search}
or decode(T.payableAmount,0,'0.00',to_char(T.payableAmount,'FM999999999990.90'))=#{search} or to_char(T.payableAmount)=#{search}
or decode(T.settFeeAmt,0,'0.00',to_char(T.settFeeAmt,'FM999999999990.90'))=#{search} or to_char(T.settFeeAmt)=#{search}
or decode(T.rate,0,'0.00',to_char(T.rate,'FM999999999990.9990'))=#{search} or to_char(T.rate)=#{search}
or replace(to_char(T.issueClass,'yyyy-MM-dd'),'-','/')=#{search}
or replace(to_char(T.payDate,'yyyy-MM-dd'),'-','/')=#{search}
)

mapper.select:
select T.issueStatus, T.finprodId, T.finprodMarketId, T.finprodAbbr, T.secManageAcctId, T.secAcctName, T.subscriptionAmount, T.payableAmount, T.settFeeAmt, T.rate, T.issueClass, T.issueDate, T.payDate, T.couponSpecies, T.intType, T.ouPartyId, T.ouPartyIdAbbr, T.issuer, T.issuerName from(
) T left join SYS_DATADICT_LIST sdl_is on T.issueStatus=sdl_is.ITEM_CODE and sdl_is.DICT_CODE='ISSUE_STATUS' left join SYS_DATADICT_LIST sdl_ist on T.issueClass=sdl_ist.ITEM_CODE and sdl_ist.DICT_CODE='ISSUE_CLASS' left join SYS_DATADICT_LIST sdl_cs on T.couponSpecies=sdl_cs.ITEM_CODE and sdl_cs.DICT_CODE='COUPON_SPECIES' left join SYS_DATADICT_LIST sdl_it on T.intType=sdl_it.ITEM_CODE and sdl_it.DICT_CODE='INT_TYPE'
AND
#{item}
AND
#{item}
AND T.ouPartyIdAbbr = #{ouParty}
AND T.issuerName = #{issuer}
order by ${pageMode.sort} ${pageMode.direction}

select validStatus, bidId, subscriptionAmount, payableAmount, ourTrader, ourTraderName, bidDate from ( select case when bo.IS_CANCEL = 'N' then '02' else '03' end validStatus, bo.BID_ID bidId, bo.SUBSCRIPTION_AMOUNT subscriptionAmount, bo.PAYABLE_AMOUNT payableAmount, bo.OU_PARTY_ID ourTrader, mcci.PARTY_ABBR ourTraderName, bo.BID_DATE bidDate from BID_ORDER bo left join BID_ORDER_BID_PRICE bobp on bo.BID_ID = bobp.BID_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID left join ETR_ENTRUST_DETAIL eed on bobp.ENTRUST_ID = eed.ENTRUST_ID and eed.PORTFOLIO_ID = bobp.PORTFOLIO_ID left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = bo.OU_PARTY_ID where bo.TRADE_STATUS != '03'
AND
#{item}
AND
#{item}
union all select '01' validStatus, wbo.BID_ID bidId, wbo.SUBSCRIPTION_AMOUNT subscriptionAmount, wbo.PAYABLE_AMOUNT payableAmount, wbo.OU_PARTY_ID ourTrader, mcci.PARTY_ABBR ourTraderName, wbo.BID_DATE bidDate from WFL_BID_ORDER wbo left join WFL_BID_ORDER_BID_PRICE wbobp on wbo.BID_ID = wbobp.BID_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = wbo.FINPROD_ID left join ETR_ENTRUST_DETAIL eed on wbobp.ENTRUST_ID = eed.ENTRUST_ID and eed.PORTFOLIO_ID = wbobp.PORTFOLIO_ID left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = wbo.OU_PARTY_ID
AND
#{item}
AND
#{item}
) order by bidDate

select * from ( select case when bo.IS_CANCEL = 'N' then '02' else '03' end validStatus, fpa.ISSUE_STATUS issueStatus, tfpdt.TRADE_DATE dealDate, bo.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, bobp.SEC_ACCT_ID secManageAcctId, fpt.TYPE_11 secType, bo.SUBSCRIPTION_AMOUNT subscriptionAmount, bo.PAYABLE_AMOUNT payableAmount, bo.SETT_FEE_AMT settFeeAmt, fpi.ISSUE_PRICE issuePrice, case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then nvl(miri.INT_RATE, 0) + nvl(fpi.REFER_YIELD, 0) else fpi.REFER_YIELD end rate, bobp.PORTFOLIO_ID portfolioId, bobp.PORTFOLIO_NAME portfolioName, fpi.ISSUE_DATE issueDate, fpi.PAY_DATE payDate, fp.COUPON_SPECIES couponSpecies, fpi.INT_TYPE intType, bo.OU_PARTY_ID ouPartyId, mcci.PARTY_ABBR ouPartyIdAbbr, fp.ISSUER issuer, mci.CUSTOMER_NAME issuerName, bo.BID_ID tradeId, tmi.TRD_ID execid, bo.REMARK remark from BID_ORDER bo left join (select listagg(t0.PORTFOLIO_ID, ',') within group (order by t0.ENTRUST_ID, t0.BID_ID) AS PORTFOLIO_ID, listagg(pp.PORTFOLIO_NAME, ',') within group (order by t0.ENTRUST_ID, t0.BID_ID) AS PORTFOLIO_NAME, t0.ENTRUST_ID ENTRUST_ID, t0.BID_ID BID_ID, eed.SEC_ACCT_ID from BID_ORDER_BID_PRICE t0 left join ETR_ENTRUST_DETAIL eed on eed.PORTFOLIO_ID = t0.PORTFOLIO_ID and eed.ENTRUST_ID = t0.ENTRUST_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = t0.PORTFOLIO_ID where t0.BID_PRICE = 99999999 group by t0.ENTRUST_ID, t0.BID_ID, eed.SEC_ACCT_ID) bobp on bo.BID_ID = bobp.BID_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = bo.FINPROD_ID left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = bo.OU_PARTY_ID left join MST_CUSTOMER_INFO mci on mci.CUSTOMER_ID = fp.ISSUER left join MST_INT_RATE_INFO miri on miri.INT_RATE_ID = fpi.INT_RATE_ID left join TRDQUTO_MATCH_INFO tmi on tmi.PRE_TRADE_ID = bo.BID_ID left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on tfpdt.TOTLE_TRADE_ID = tmi.TRD_ID where bo.TRADE_STATUS != '03'
AND bobp.ENTRUST_ID = #{entrustId}
union all select '01' validStatus, fpa.ISSUE_STATUS issueStatus, tfpdt.TRADE_DATE dealDate, bo.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, bobp.SEC_ACCT_ID secManageAcctId, fpt.TYPE_11 secType, bo.SUBSCRIPTION_AMOUNT subscriptionAmount, bo.PAYABLE_AMOUNT payableAmount, bo.SETT_FEE_AMT settFeeAmt, fpi.ISSUE_PRICE issuePrice, case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then nvl(miri.INT_RATE, 0) + nvl(fpi.REFER_YIELD, 0) else fpi.REFER_YIELD end rate, bobp.PORTFOLIO_ID portfolioId, bobp.PORTFOLIO_NAME portfolioName, fpi.ISSUE_DATE issueDate, fpi.PAY_DATE payDate, fp.COUPON_SPECIES couponSpecies, fpi.INT_TYPE intType, bo.OU_PARTY_ID ouPartyId, mcci.PARTY_ABBR ouPartyIdAbbr, fp.ISSUER issuer, mci.CUSTOMER_NAME issuerName, bo.BID_ID tradeId, tmi.TRD_ID execid, bo.REMARK remark from WFL_BID_ORDER bo left join (select listagg(t0.PORTFOLIO_ID, ',') within group (order by t0.ENTRUST_ID, t0.BID_ID) AS PORTFOLIO_ID, listagg(pp.PORTFOLIO_NAME, ',') within group (order by t0.ENTRUST_ID, t0.BID_ID) AS PORTFOLIO_NAME, t0.ENTRUST_ID ENTRUST_ID, t0.BID_ID BID_ID, eed.SEC_ACCT_ID from WFL_BID_ORDER_BID_PRICE t0 left join ETR_ENTRUST_DETAIL eed on eed.PORTFOLIO_ID = t0.PORTFOLIO_ID and eed.ENTRUST_ID = t0.ENTRUST_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = t0.PORTFOLIO_ID where t0.BID_PRICE = 99999999 group by t0.ENTRUST_ID, t0.BID_ID, eed.SEC_ACCT_ID) bobp on bo.BID_ID = bobp.BID_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID = bo.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = bo.FINPROD_ID left join MST_CFETS_CUSTOMER_INFO mcci on mcci.PARTY_ID = bo.OU_PARTY_ID left join MST_CUSTOMER_INFO mci on mci.CUSTOMER_ID = fp.ISSUER left join MST_INT_RATE_INFO miri on miri.INT_RATE_ID = fpi.INT_RATE_ID left join TRDQUTO_MATCH_INFO tmi on tmi.PRE_TRADE_ID = bo.BID_ID left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on tfpdt.TOTLE_TRADE_ID = tmi.TRD_ID
bobp.ENTRUST_ID = #{entrustId}
) T
order by ${pageMode.sort} ${pageMode.direction}
